<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/certificate-auth.php';
$user=fleet_cert_require_user();fleet_cert_require_permission($user,'users.manage');
try {
    $db=fleet_db();
    if(($_SERVER['REQUEST_METHOD']??'GET')==='GET'){
        $controller=in_array('APP_CONTROLLER',$user['roles']??[],true);
        $staffSql=$controller?'SELECT u.id,u.full_name,u.username,u.email,u.is_active,GROUP_CONCAT(r.role_name ORDER BY r.role_name SEPARATOR ", ") roles FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id GROUP BY u.id ORDER BY u.full_name':'SELECT u.id,u.full_name,u.username,u.email,u.is_active,GROUP_CONCAT(r.role_name ORDER BY r.role_name SEPARATOR ", ") roles FROM users u LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id WHERE NOT EXISTS (SELECT 1 FROM user_roles x JOIN roles xr ON xr.id=x.role_id WHERE x.user_id=u.id AND xr.role_name=\'APP_CONTROLLER\') GROUP BY u.id ORDER BY u.full_name';$staffQuery=$db->prepare($staffSql);$staffQuery->execute();$rows=$staffQuery->fetchAll();
        $isController=in_array('APP_CONTROLLER',$user['roles']??[],true);$roles=$db->query('SELECT id,role_name FROM roles ORDER BY role_name')->fetchAll();if(!$isController)$roles=array_values(array_filter($roles,static fn($r)=>$r['role_name']!=='APP_CONTROLLER'));json_response(['ok'=>true,'users'=>$rows,'roles'=>$roles,'current_user_id'=>(int)$user['id'],'is_app_controller'=>$isController]);
    }
    fleet_cert_require_same_origin_post();
    $input=json_decode((string)file_get_contents('php://input'),true);if(!is_array($input))json_response(['ok'=>false,'message'=>'Invalid user request.'],400);
    if(($input['action']??'')==='set_active'){
        $targetId=(int)($input['user_id']??0);$active=filter_var($input['is_active']??null,FILTER_VALIDATE_BOOLEAN,FILTER_NULL_ON_FAILURE);if($targetId<1||$active===null)json_response(['ok'=>false,'message'=>'Choose a valid user and active or disabled state.'],400);if($targetId===(int)$user['id']&&!$active)json_response(['ok'=>false,'message'=>'You cannot disable your own account.'],400);
        $db->beginTransaction();try{$q=$db->prepare('SELECT id,is_active FROM users WHERE id=? FOR UPDATE');$q->execute([$targetId]);$target=$q->fetch();if(!$target)throw new InvalidArgumentException('That user account no longer exists.');$q=$db->prepare("SELECT r.role_name FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=?");$q->execute([$targetId]);$targetRoles=$q->fetchAll(PDO::FETCH_COLUMN);$controller=in_array('APP_CONTROLLER',$user['roles']??[],true);if(in_array('APP_CONTROLLER',$targetRoles,true)&&!$controller)throw new InvalidArgumentException('Only the App Controller can enable or disable the App Controller account.');if(in_array('APP_CONTROLLER',$targetRoles,true)&&!$active){$q=$db->prepare("SELECT COUNT(*) FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.is_active=1 AND r.role_name='APP_CONTROLLER' AND u.id<>?");$q->execute([$targetId]);if((int)$q->fetchColumn()===0)throw new InvalidArgumentException('The last active App Controller cannot be disabled.');}$db->prepare('UPDATE users SET is_active=? WHERE id=?')->execute([$active?1:0,$targetId]);$verb=$active?'enabled':'disabled';fleet_cert_log($db,(int)$user['id'],strtoupper($verb),'USER',$targetId,ucfirst($verb).' user account '.$targetId.'.');$db->commit();json_response(['ok'=>true,'message'=>'User account '.$verb.'.']);}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();json_response(['ok'=>false,'message'=>$e->getMessage()],400);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
    }
    $name=trim((string)($input['full_name']??''));$email=strtolower(trim((string)($input['email']??'')));$username=trim((string)($input['username']??''));if($username===''&&$email!=='')$username=substr(preg_replace('/[^A-Za-z0-9._-]/','_',strstr($email,'@',true)?:'workspace_user'),0,80);$roleId=(int)($input['role_id']??0);$role=strtoupper(trim((string)($input['role']??'')));
    if($roleId){$roleStmt=$db->prepare('SELECT role_name FROM roles WHERE id=? LIMIT 1');$roleStmt->execute([$roleId]);$roleName=(string)$roleStmt->fetchColumn();}else{$roleStmt=$db->prepare('SELECT id,role_name FROM roles WHERE role_name=? LIMIT 1');$roleStmt->execute([$role]);$roleRow=$roleStmt->fetch();$roleId=(int)($roleRow['id']??0);$roleName=(string)($roleRow['role_name']??'');}if($roleName==='APP_CONTROLLER'&&!in_array('APP_CONTROLLER',$user['roles']??[],true))json_response(['ok'=>false,'message'=>'Only the App Controller can assign the App Controller role.'],403);
    if($name===''||!preg_match('/^[A-Za-z0-9._-]{3,80}$/',$username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||($roleId>0&&!$roleName))json_response(['ok'=>false,'message'=>'Enter a full name and valid Google Workspace email. Select a role now or leave it unassigned.'],400);
    $db->beginTransaction();try{$stmt=$db->prepare('INSERT INTO users (full_name,username,email,password_hash,is_active) VALUES (?,?,?,NULL,1)');$stmt->execute([$name,$username,$email]);$id=(int)$db->lastInsertId();if($roleId){$link=$db->prepare('INSERT INTO user_roles (user_id,role_id) VALUES (?,?)');$link->execute([$id,$roleId]);}$assignment=$roleId?' with role '.$roleName:' without a role (pending access assignment)';fleet_cert_log($db,(int)$user['id'],'CREATE','USER',$id,'Created passwordless Workspace user '.$email.$assignment.'.');$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
    json_response(['ok'=>true,'message'=>$roleId?'Passwordless user created. They can sign in with Google Workspace.':'User created without a role. They will see the access-pending welcome page after Google sign-in.']);
}catch(Throwable $e){if(isset($db)&&$db instanceof PDO&&$db->inTransaction())$db->rollBack();error_log('Certificate user management: '.$e->getMessage());json_response(['ok'=>false,'message'=>'Could not save the user. Check that the username or email is not already in use.'],500);}
